const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
let person=PEOPLE[1],year=1080,full=false,timer=null,landData=null,view=[98,18,124,43];
const labelYear=y=>y<0?`公元前 ${-y} 年`:`${y} 年`;
function svg(tag,attrs={},text){const el=document.createElementNS(NS,tag);for(const [k,v]of Object.entries(attrs))el.setAttribute(k,v);if(text!==undefined)el.textContent=text;return el;}
function project(p){return [(p[0]-view[0])/(view[2]-view[0])*1000,650-(p[1]-view[1])/(view[3]-view[1])*650];}
function path(points,close=false){return points.map((p,i)=>`${i?'L':'M'}${project(p).map(v=>v.toFixed(1)).join(',')}`).join(' ')+(close?'Z':'');}
function fit(){const xs=person.nodes.map(n=>n.xy[0]),ys=person.nodes.map(n=>n.xy[1]);let minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);let w=Math.max(20,maxX-minX+12),h=Math.max(20,maxY-minY+15);if(w/h<1.2)w=h*1.2;const cx=(minX+maxX)/2,cy=(minY+maxY)/2+2;view=[cx-w/2,cy-h/2,cx+w/2,cy+h/2];draw();}
function era(y){if(y< -206)return ['秦','统一与帝国的开端'];if(y<25)return ['汉','帝国与远方'];if(y<220)return ['东汉','政治、学术与边疆'];if(y<280)return ['三国','多个政权并立'];if(y<420)return ['两晋','迁徙与地域变化'];if(y<581)return ['南北朝','南北政权并立'];if(y<618)return ['隋','重新走向统一'];if(y<907)return ['唐','东西之间的往来'];if(y<960)return ['五代十国','多个政权交替与并存'];if(y<1127)return ['北宋','宋、辽、西夏等政权并立'];if(y<1279)return ['南宋时期','宋、金及蒙古等政权的格局随年变化'];if(y<1368)return ['元','连接不同区域的时代'];if(y<1644)return ['明','地方生活与远方世界'];if(y<1912)return ['清','政权更替、地域联系与社会变化'];return ['民国时期','时代激荡中的个人道路'];}
function currentIndex(){let i=-1;person.nodes.forEach((n,j)=>{if(n.year<=year)i=j});return i;}
function drawLand(){const target=$('land');target.replaceChildren();if(!landData)return;for(const f of landData.features){const polygons=f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[f.geometry.coordinates];for(const polygon of polygons){target.append(svg('path',{d:polygon.map(r=>path(r,true)).join(' '),fill:'#f1f0df',stroke:'#bcc7b7','stroke-width':1,'fill-rule':'evenodd'}));}}}
function drawPolitics(){const g=$('political-layer');g.replaceChildren();if(!$('politics').checked)return;const y=year;let shapes=[];
// Deliberately abstract regions, never imported or presented as historical boundaries.
if(y>=960&&y<1127)shapes=[['北宋',[[104,33],[110,37],[118,37],[122,31],[119,24],[110,22],[103,27]], [111,30]],['辽',[[111,41],[119,45],[126,44],[126,39],[119,37]], [120,41]],['西夏',[[98,38],[104,41],[108,38],[106,35],[100,35]],[102,38]]];
else if(y>=1127&&y<1279)shapes=[['南宋',[[104,31],[111,33],[119,33],[122,29],[118,23],[110,22],[103,27]],[113,27]],['北方政权',[[103,35],[110,42],[120,42],[123,35],[117,33],[108,33]],[113,37]]];
else if(y>=618&&y<907)shapes=[['唐',[[102,36],[111,41],[121,39],[122,30],[114,23],[105,24],[101,30]],[112,32]],['吐蕃',[[81,31],[90,35],[99,34],[101,29],[90,27]],[91,31]]];
else if(y>=1368&&y<1644)shapes=[['明',[[102,34],[112,41],[121,40],[124,33],[121,27],[114,22],[106,22],[99,26]],[112,32]]];
else if(y>=1644&&y<1912)shapes=[['清',[[98,36],[110,44],[124,45],[130,41],[122,31],[120,24],[110,21],[101,24]],[112,33]]];
for(const [name,points,center]of shapes){g.append(svg('path',{d:path(points,true),fill:'#a5b491','fill-opacity':'.19',stroke:'#94a284','stroke-width':1.2,'stroke-dasharray':'5 7'}));const [x,y]=project(center);g.append(svg('text',{x,y,class:'region-label','text-anchor':'middle'},name));}
}
function draw(){drawLand();drawPolitics();const labels=$('geo-labels');labels.replaceChildren();for(const [name,point]of [['东 海',[126,28]],['南 海',[116,17]],['喜 马 拉 雅',[85,29]]]){const [x,y]=project(point);labels.append(svg('text',{x,y,class:'ocean-label'},name));}
const wars=$('war-layer');wars.replaceChildren();if($('wars').checked)for(const w of WARS.filter(w=>year>=w.year&&year<=w.until)){const [x,y]=project(w.xy),g=svg('g');g.append(svg('path',{d:`M${x} ${y-9}l9 9-9 9-9-9Z`,fill:'#9c7b54',opacity:.8}));g.append(svg('text',{x:x+14,y:y-14,'font-size':11},w.name));g.append(svg('title',{},w.text));wars.append(g);}
const g=$('route-layer');g.replaceChildren();if(!$('route').checked)return;const i=currentIndex();if(i<0||year>person.end)return;const nodes=person.nodes.slice(0,i+1);if(nodes.length>1)g.append(svg('path',{d:path(nodes.map(n=>n.xy)),fill:'none',stroke:person.color,'stroke-width':2.4,'stroke-dasharray':'6 5','stroke-linejoin':'round'}));nodes.forEach((n,j)=>{const [x,y]=project(n.xy),group=svg('g',{'data-node':j,role:'button',tabindex:0,'aria-label':`${n.year}年 ${n.place}，跳转此节点`,style:'cursor:pointer'});group.append(svg('circle',{cx:x,cy:y,r:j===i?8:4,fill:j===i?person.color:'#f8f4e7',stroke:person.color,'stroke-width':2}));if(j===i){group.append(svg('circle',{cx:x,cy:y,r:16,fill:'none',stroke:person.color,'stroke-opacity':.3,'stroke-width':1.5}));}group.append(svg('text',{x:x+13,y:y+(j%2?-13:20),'font-size':12},n.place));group.append(svg('title',{},`${n.year} · ${n.title}`));group.addEventListener('click',()=>jump(n.year));group.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();jump(n.year);}});g.append(group);});}
function renderPeople(){$('people').innerHTML=PEOPLE.map(p=>`<button class="person ${p.id===person.id?'active':''}" data-person="${p.id}" aria-pressed="${p.id===person.id}"><span class="monogram">${p.name[0]}</span><span><strong>${p.name}</strong><small>${p.tag}</small></span></button>`).join('');document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{stop();person=PEOPLE.find(p=>p.id===b.dataset.person);full=false;year=person.nodes[Math.min(3,person.nodes.length-1)].year;renderPeople();setRange();fit();render();});}
function setRange(){const min=full?-221:person.birth,max=full?1949:person.end;$('time').min=min;$('time').max=max;$('range-start').textContent=labelYear(min);$('range-end').textContent=labelYear(max);$('scope').textContent=full?'聚焦人物一生':'切换至完整历史';$('life-range').textContent=`${person.name} · ${person.birth}—${person.end}`;$('ticks').innerHTML=person.nodes.map(n=>`<i class="tick" style="left:${(n.year-min)/(max-min)*100}%"></i>`).join('');}
function render(){const i=currentIndex(),before=year<person.birth,after=year>person.end,n=person.nodes[Math.max(i,0)],exact=!before&&!after&&n.year===year;const [name,subtitle]=era(year);$('era-title').textContent=name;$('era-sub').textContent=subtitle;$('time').value=year;$('current-year').textContent=labelYear(year);$('year-label').textContent=year<0?`前${-year}`:year;$('age-label').textContent=before?'尚未出生':after?'已超出展示生涯':`约 ${year-person.birth} 岁`;$('step-count').textContent=before||after?'—':`${String(i+1).padStart(2,'0')} / ${String(person.nodes.length).padStart(2,'0')}`;
$('place-label').textContent=before||after?'暂无对应人生节点':`${exact?'● 所选年份记录':'◌ 最近记录'} · ${n.place}`;$('event-title').textContent=before?'这段人生尚未开始':after?'这段人生已结束展示':exact?n.title:'这一年，位置尚未确定';$('event-desc').textContent=before?`${person.name}的样本从${person.birth}年开始。可以切回“聚焦人物一生”，或继续浏览历史时间。`:after?`此人物展示窗口截至${person.end}年。${person.id==='liqingzhao'?'她的卒年存在争议，此处采用常见说法。':'可切换其他人物，继续阅读时代。'}`:exact?n.text:`最近一条样本记录来自${n.year}年：${n.place}，${n.title}。地图保留该记录的位置，不代表${year}年仍在当地。`;$('evidence').textContent=before||after?'全历史模式 · 六人样本仅覆盖各自人生的部分年份':exact?(n.note||'年份级编辑样本 · 坐标为现代地点近似值，连线不是实际道路。'):'史料空白不做插值，不把未知位置画成确定行程。';$('location-legend').textContent=exact?'所选年份记录':'最近记录（非当前定位）';const war=WARS.find(w=>year>=w.year&&year<=w.until);$('context').textContent=war?war.text:year>=1069&&year<1127?'北宋政治变革与党争，影响着士人的任职、交往和生活选择。':`${name} · ${subtitle}。政治图层为示意，尚未逐年核验边界；战事图层只含少量样本事件。`;$('node-count').textContent=`${person.nodes.length} 个样本`;$('events').innerHTML=person.nodes.map((e,j)=>`<button class="event ${!before&&!after&&j===i?'active':''} ${e.year>year?'future':''}" data-year="${e.year}"><b>${e.year}</b>${e.place}</button>`).join('');document.querySelectorAll('[data-year]').forEach(b=>b.onclick=()=>jump(Number(b.dataset.year)));draw();}
function jump(y){stop();year=y;render();}
function stop(){if(timer)clearInterval(timer);timer=null;$('play').textContent='▶';$('play').setAttribute('aria-label','播放时间轴');}
function play(){if(timer){stop();return;}if(year>=Number($('time').max))year=Number($('time').min);$('play').textContent='Ⅱ';$('play').setAttribute('aria-label','暂停时间轴');timer=setInterval(()=>{year+=full?10:1;if(year===0)year=1;if(year>=Number($('time').max)){year=Number($('time').max);stop();}render();},Number($('speed').value));}
function modal(html){$('modal-content').innerHTML=html;$('modal').showModal();}
function roster(){modal(`<h2>四十六个人，一卷中国史。</h2><p>公元前221年至1949年 · 26名男性、20名女性。每个章节至少一男一女，跨时代人物保留完整人生。下列是已确认的候选框架，资料仍需逐人核验。</p><table><thead><tr><th>历史章节</th><th>男性候选</th><th>女性候选</th></tr></thead><tbody>${ROSTER.map(r=>'<tr>'+r.map(v=>`<td>${v}</td>`).join('')+'</tr>').join('')}</tbody></table><p>首批原型：玄奘、苏轼、徐霞客、李清照、秦良玉、秋瑾。其余人物尚未录入地图。</p>`);}
$('roster-open').onclick=roster;$('roster-more').onclick=roster;$('about-open').onclick=()=>modal('<h2>让确定与未知，都被看见。</h2><p>这是六个人物的交互验证原型，不是完整历史地理数据库。我们保留每个样本的资料入口，并将在正式版本逐条核验年谱、原始出处与地图坐标。</p><ul><li>陆地轮廓来自 Natural Earth 1:110m 公共领域数据；不显示现代国界。</li><li>政治色块是原创的粗略交互示意，不能用于判断历史归属或实际控制范围；尚未制作完整疆界变化。</li><li>路线是已发生的样本节点之间的连接，不是经过考证的道路、水路或行军路线。</li><li>时间轴停在空白年份时，只标记最近的记录，不推测人物的当前所在地。</li><li>年龄按年份差估算，年内日期尚未对齐；未导入 CBDB 或 CHGIS 数据。</li><li>战争层仅展示少量相关事件，未展示完整战线；出生模拟留待后续阶段。</li></ul><p><a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener">Natural Earth 数据条款 ↗</a></p>');$('source-open').onclick=()=>modal(`<h2>${person.name} · 资料与边界</h2><p>${person.caveat}</p><ul class="source-list">${person.sources.map(([name,url])=>`<li><a href="${url}" target="_blank" rel="noopener">${name} ↗</a></li>`).join('')}</ul><p>以上为人物资料入口，并非每个节点都已完成逐条引文核验。古今地点采用现代近似坐标；史料有争议的节点须在正式版本进一步复核。</p>`);$('close-modal').onclick=()=>$('modal').close();$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('modal').close();}});
$('time').oninput=e=>{stop();year=Number(e.target.value);if(year===0)year=1;render();};$('scope').onclick=()=>{stop();full=!full;if(!full)year=Math.max(person.birth,Math.min(person.end,year));setRange();render();};$('play').onclick=play;$('speed').onchange=()=>{if(timer){stop();play();}};$('prev').onclick=()=>jump([...person.nodes].reverse().find(n=>n.year<year)?.year??person.birth);$('next').onclick=()=>jump(person.nodes.find(n=>n.year>year)?.year??person.end);$('fit').onclick=fit;for(const id of ['politics','wars','route'])$(id).onchange=draw;document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});renderPeople();setRange();fit();render();fetch('land.json').then(r=>{if(!r.ok)throw Error('底图不可用');return r.json();}).then(data=>{landData=data;draw();}).catch(()=>{$('era-sub').textContent+=' · 地理底图加载失败，请刷新';});
